insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('59','69','Silver not confirmed as sterling — look for a 925 stamp.; Most pieces still need to be measured.','Sterling vs silver-plated is a meaningful price difference and a claim you must be able to back.; Size is a required field on most selling platforms and the commonest pre-purchase question.','f','2026-07-24 16:18:22.753726+00');
insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('60','70','Silver not confirmed as sterling — look for a 925 stamp.; Stone unresolved: dumortierite-in-quartz vs azurite vs blue-spot jasper.','Sterling vs silver-plated is a meaningful price difference and a claim you must be able to back.; Same reasoning — hold the specific name out of the title until confirmed.','f','2026-07-24 16:18:22.753726+00');
insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('61','71','Stone unresolved: thulite/rhodonite vs dyed quartzite.; Most pieces still need to be measured.','Affects both price and whether a dye disclosure is required.; Size is a required field on most selling platforms and the commonest pre-purchase question.','f','2026-07-24 16:18:22.753726+00');
