insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('65','77','Stone identified by eye only as blue jasper/agate. No slip found.; Most pieces still need to be measured.','A wrong stone name in the title is the kind of error that draws returns.; Size is a required field on most selling platforms and the commonest pre-purchase question.','f','2026-07-24 16:18:22.753726+00');
insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('66','78','Most pieces still need to be measured.','Size is a required field on most selling platforms and the commonest pre-purchase question.','f','2026-07-24 16:18:22.753726+00');
insert into public.follow_up (id, piece_id, open_question, why_it_matters, resolved, created_at) values ('67','79','Two bags appear to read 1134. Bumblebee jasper bee pendant may actually be 1154.; Most pieces still need to be measured.','Duplicate SKUs will corrupt the Sales Log lookup. Re-read the bag before listing either piece.; Size is a required field on most selling platforms and the commonest pre-purchase question.','f','2026-07-24 16:18:22.753726+00');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('1','Sterling stamp (925)','Loupe or magnifier on clasps, spacers, bead caps and accent beads. Look for 925, ALE 925, or a maker''s mark.','Moves several pieces from B to C. NK-002 and BR-034 carry the most metal; BR-011''s leaf toggle is the single highest-value unknown.','BR-004, BR-011, NK-001, NK-002, BR-015, BR-017, BR-023, NK-005, BR-029, BR-030, BR-034, BR-035 | also (pendants/buyout): BR-048, PN-009, PN-010, PN-012, PN-013','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('2','Black bead: onyx or glass','Onyx is cold to the touch and heavy for its size; glass warms fast and feels light. Check under bright light for internal bubbles - bubbles mean glass.','NK-001 is a 24-26in strand of 10mm beads, so the answer moves real money. BR-027 drops to A if glass.','NK-001, BR-027, NK-007','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('3','Gold-filled vs. plated','Look for ''GF'' or ''14/20'' on the chain end links or clasp tag. Gold-fill stays bright at friction points; plate dulls or shows copper.','Both move from B to C if gold-filled. Both chains still look bright for their age, which is a good sign.','NK-006, NK-008','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('4','Tourmaline backlight test','Hold the beads against a strong light. Tourmaline glows through with colour; opaque jasper or agate will not.','A full tier. If tourmaline, this needs individual comps rather than category pricing.','BR-019','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('5','Lapis vs. sodalite','Look for tiny gold metallic pyrite flecks under bright light. Lapis has them; sodalite does not.','Listing title only - both stay in their current tier either way. (BR-034 already confirmed as lapis.)','BR-001, BR-020','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('6','Coral: natural, dyed or substitute','Compare the three coral pieces side by side. Uniform colour within a group indicates dye. Settle on one phrase and use it across all three.','Listing accuracy. ''Dyed bamboo coral'' is the honest phrasing and also answers sourcing questions.','BR-004, BR-009, BR-024','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('7','Pearls: cultured or glass','Real pearls show growth ridging, size variation and blemishes. Glass is uniform.','Part of the three-way check on this necklace. (BR-011, BR-014 and NK-004 pearls already confirmed real.)','NK-006','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('8','Sally''s tag reverses','Flip every tag. Several carry her handwritten materials notes, which have been accurate on every piece so far.','Her notes are primary evidence for materials. Record her exact wording.','BR-005, BR-023, and any tag not yet turned over','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('9','Charm bead hallmarks','Magnifier on every metal bead. Branded beads (ALE 925, Chamilia, Trollbeads) have real individual resale value; generic compatible beads do not.','Decides whether to sell whole or part out. Do not disassemble before checking.','NK-005','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('10','Stone ID: amazonite family','Compare SW-018 and SW-029 in hand. If weight and feel match, call both amazonite.','Listing accuracy only.','BR-016, BR-025','f');
insert into public.verification_check (id, check_name, how_to, what_it_changes, pieces_affected_raw, is_resolved) values ('11','RESOLVED - pendant ID (SW-040)','Additional photo of the polished face settled it: the spiral of chambered whorls with suture lines is an ammonite fossil, not druzy agate. The crystalline pockets are calcite-filled chambers seen from the uncut side.','No tier change (still C), but the listing terms change entirely - search ammonite, not druzy. Adds a fossil/natural-history audience alongside jewelry buyers.','NK-007','t');
