insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('1','PN-015','Mohave purple turquoise is natural turquoise that is dyed and bronze-bonded — a composite, not plain turquoise.','"Mohave purple turquoise (stabilized / dyed composite)"');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('2','PN-015, PN-011, PN-019','Mixed metals: gold-filled wire with gold-plated findings.','State both plainly. Gold-fill buyers care about the distinction.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('3','PN-018, PN-019','Bumblebee jasper is not jasper; it is volcanic sediment containing realgar and orpiment (arsenic sulfides). Safe to wear as a sealed cabochon; must not be cut or ground unprotected.','Disclose composition in the listing. Collectors of this stone already know and read it as a trust signal.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('4','PN-014','That saturated magenta is not a natural chalcedony color.','"Dyed pink chalcedony" — not ''pink onyx'' or ''cherry quartz''.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('5','PN-016','Citrine at this even lemon tone is heat-treated, as is nearly all citrine on the market.','Use "citrine" (Sally''s own word). Do NOT add "natural".');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('6','ST-002','Black and brown sparkle hearts are goldstone — manmade glass with copper flecks.','Must be labeled as glass. Green heart may be reconstituted malachite — check banding regularity.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('7','ST-001, NK-012','Uniform sky-blue beads with fine black webbing are dyed howlite or magnesite, not turquoise.','"Turquoise-colored howlite" or "stabilized dyed magnesite".');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('8','ST-003','"Lemon jade" is a trade name; the material is usually serpentine.','"Lemon jade (serpentine)" — keeps the search term without a jade claim.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('9','BR-044, BR-045','Peacock purple-to-blue shift across facets is an aurora borealis vacuum coating on glass.','"Faceted glass" or "crystal." Never amethyst.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('10','NK-010','Bicone shape is Swarovski-style but also made by several Czech and Chinese producers.','"Crystal bicone beads" — no brand claim without a receipt or original packaging.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('11','PN-013','Seven beads in spectrum order is a deliberate chakra sequence.','"Chakra" is a high-traffic search term — carry it into tags and description.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('12','PN-013, PN-017','Dichroic is fused art glass, not a natural stone; collectors search it by name.','Say "dichroic art glass" explicitly.');
insert into public.listing_disclosure (id, applies_to_raw, disclosure_point, recommended_wording) values ('13','NK-011, NK-012','Handwritten $35 / $30 tags may be the previous seller''s pricing, not Sally''s.','Treat as historical reference in the Existing Tag Price column, not as asking prices.');
