insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('1','Copper trio','BR-013, BR-025, BR-026','Identical trefoil bead caps, copper disc spacers and copper lobster clasps. Same maker, same findings drawer, three colourways (yellow, pale blue, magenta). All tagged $20.','Strongest lot candidate in the batch. One listing, one shipment, and the matched findings make the grouping look intentional. Clean BR-013''s verdigris first.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('2','Cloisonne + foil glass trio','BR-001, BR-032, BR-033','Identical fluted gold-tone tube links and construction logic across all three.','List together or note the family in each listing. Reseat BR-033''s bent bead caps first.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('3','Charm bracelet group','BR-006, BR-007, BR-018','Same AB crystal stock and charm-drop construction; clear, peach and amber colourways.','Two- or three-piece lot. Lead with BR-018 (celestial heart) if listing individually.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('4','Glass bundle','BR-006, BR-007, BR-015, BR-018','All glass and base metal, all photograph better than they price.','More efficient to sell as a lot than four separate low-margin listings.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('5','A-tier bundle','BR-005, BR-009','Real stone in the cheapest cut, simplest construction, $13-25 tags.','Individually low-margin after fees and shipping. Themed lots of three or four move better.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('6','Mixed quartz pair','BR-028, BR-030','Same stone palette and tumbled nugget cut; differ only in spacer finish.','Matched-but-not-identical sells well. Listing as a pair may outperform two singles.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('7','Amethyst coin pair','BR-023, BR-035','Both Sally''s, both $15, same amethyst coin beads, different partner stone.','Natural pair. Amethyst is also a searchable through-line across NK-003, NK-004, BR-028 and BR-030.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('8','Bali silver group','NK-002, BR-017, BR-034','Same granulated Bali-style spacer pattern across a necklace and two bracelets.','Not necessarily a sales lot, but check all three for 925 in one sitting.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('9','Filigree + rhinestone pair','BR-016, BR-027','Same gold filigree ball beads, corrugated rounds, prong-set rhinestone rondelles and clasp style. Green and red colourways.','Made as a set or in close sequence. Would list well as a pair.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('10','Tiger''s eye matched pair','BR-036, BR-040','Two individual bracelets made as a matched pair. Each is separately priced and labeled with its own tags.','Sell as a pair or as two singles. A matched pair of handmade bracelets is an unusual offer and worth trying as one listing first.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('11','Smoky + lemon quartz matched pair','BR-038, BR-041','Two individual bracelets made as a matched pair. Each is separately priced and labeled with its own tags.','Same handling. Two natural quartzes, clean construction - these should photograph well side by side.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('12','Bee collection','PN-011, PN-019','Three bee-themed pieces total (1144, 1153, 1134/1154 group).','Cross-link as a bee collection. Bee-jewelry buyers collect rather than buy once.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('13','Angel collection','PN-013, PN-017','Two angels: one gold (1152), one silver (1146).','Group as an "Angel Collection" so buyers browse rather than buy one and leave.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('14','Cloisonné pair','BR-046, BR-047','Two cloisonné bracelets, same design, complementary colorways.','Sell as a pair; photograph side by side and stacked.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('15','Purple AB set','BR-044, BR-045','Two purple AB bracelets, same colorway, different spacers.','Sell as a stacking set.');
insert into public.lot_candidate (id, group_name, pieces_raw, why_grouped, suggested_handling) values ('16','Rose quartz lot','ST-004','Six identical rose quartz strands.','Sell as one lot to a reseller, crystal shop, or bridal buyer — five near-identical listings compete with each other.');
